12.query:
// 1. START WITH METADATA (Source of Truth)
fetch bizevents, from: now()-72h
| filter dt.system.bucket == "archer" and Criticality != "" and Status == "Active"
| fieldsAdd Shortname = lower(trim(`Application Short Name`))
| summarize {
Criticality = takeFirst(Criticality),
Portfolio = takeFirst(Portfolio)
}, by:{ Shortname }

// 2. LOOKUPS (OneAgent, Traces, RUM, Synthetics)
| lookup [fetch dt.entity.host | expand tags | fieldsAdd tags = lower(tags) | parse tags, "DATA* 'shortname' DATA* ':' DATA:tag_sn" | summarize h_c = count(), by:{ tag_sn = lower(trim(tag_sn)) }], sourceField: Shortname, lookupField: tag_sn, fields:{ h_c }
| lookup [fetch dt.entity.service | expand tags | fieldsAdd tags = lower(tags) | parse tags, "DATA* 'shortname' DATA* ':' DATA:tag_sn" | summarize t_c = count(), by:{ tag_sn = lower(trim(tag_sn)) }], sourceField: Shortname, lookupField: tag_sn, fields:{ t_c }
| lookup [fetch dt.entity.application | expand tags | fieldsAdd tags = lower(tags) | parse tags, "DATA* 'shortname' DATA* ':' DATA:tag_sn" | summarize r_c = count(), by:{ tag_sn = lower(trim(tag_sn)) }], sourceField: Shortname, lookupField: tag_sn, fields:{ r_c }
| lookup [fetch dt.entity.synthetic_test | append [fetch dt.entity.http_check] | append [fetch dt.entity.multiprotocol_monitor] | expand tags | fieldsAdd tags = lower(tags) | parse tags, "DATA* 'shortname' DATA* ':' DATA:tag_sn" | summarize s_exists = count() > 0, by:{ tag_sn = lower(trim(tag_sn)) }], sourceField: Shortname, lookupField: tag_sn, fields:{ s_exists }

// 3. DEFINE ACTIVE MONITORING (Excluding Logs as per your logic)
| fieldsAdd 
h = coalesce(h_c, 0), 
t = coalesce(t_c, 0), 
r = coalesce(r_c, 0), 
s = coalesce(s_exists, false)
| fieldsAdd is_monitored = (h > 0 or t > 0 or r > 0 or s == true)

// 4. CALCULATE PERCENTAGES
| summarize {
`Total Applications` = count(),
`Monitored Applications` = countIf(is_monitored == true),
`Unmonitored Applications` = countIf(is_monitored == false)
}
| fieldsAdd 
Ratio = (toDouble(`Monitored Applications`) / toDouble(`Total Applications`)) * 100
| fieldsAdd 
`Monitoring Coverage %` = concat(toLong(Ratio), "%")

// 5. FINAL VIEW
| fields `Total Applications`, `Monitored Applications`, `Unmonitored Applications`, `Monitoring Coverage %`

