23.query:
// 1. START WITH METADATA
fetch bizevents, from: now()-72h
| filter dt.system.bucket == "archer" and Criticality != "" and Status == "Active"
| fieldsAdd Shortname = lower(trim(`Application Short Name`))
| summarize {
Criticality = takeFirst(Criticality),
Owner = takeFirst(`Application Owner`),
Lead = takeFirst(`Technical Lead`),
Portfolio = takeFirst(Portfolio),
MD = takeFirst(`Managing Director`),
VP = takeFirst(`VP`),
Status = takeFirst(`Status`)
}, by:{ Shortname }

// 2. CHECK FOR ONEAGENT (HOSTS)
| lookup [
fetch dt.entity.host
| expand tags | fieldsAdd tags = lower(tags)
| filter matchesphrase(tags, "shortname:") and not startsWith(tags, "[Environment]")
| parse tags, "DATA* 'shortname' DATA* ':' DATA:tag_sn"
| summarize host_count = count(), by:{ tag_sn = lower(trim(tag_sn)) }
], sourceField: Shortname, lookupField: tag_sn, fields:{ host_count }

// 3. CHECK FOR TRACES (SERVICES)
| lookup [
fetch dt.entity.service
| expand tags | fieldsAdd tags = lower(tags)
| filter matchesphrase(tags, "shortname:") and not startsWith(tags, "[Environment]")
| parse tags, "DATA* 'shortname' DATA* ':' DATA:tag_sn"
| summarize trace_count = count(), by:{ tag_sn = lower(trim(tag_sn)) }
], sourceField: Shortname, lookupField: tag_sn, fields:{ trace_count }

// 4. CHECK FOR LOGS
| lookup [
fetch logs, from:now()-24h, samplingRatio:1000
| filter isNotNull(dt.security_context)
| summarize log_exists = count() > 0, by:{ log_sn = lower(dt.security_context) }
], sourceField: Shortname, lookupField: log_sn, fields:{ log_exists }

// 5. CHECK FOR RUM (Real User Monitoring / Applications)
| lookup [
fetch dt.entity.application
| expand tags | fieldsAdd tags = lower(tags)
| filter matchesphrase(tags, "shortname:")
| parse tags, "DATA* 'shortname' DATA* ':' DATA:tag_sn"
| summarize rum_count = count(), by:{ tag_sn = lower(trim(tag_sn)) }
], sourceField: Shortname, lookupField: tag_sn, fields:{ rum_count }

// 6. SYNTHETICS
| lookup [
fetch dt.entity.synthetic_test | expand tags | fieldsAdd tags = lower(tags)
| parse tags, "DATA* 'shortname' DATA* ':' DATA:tag_sn"
| summarize has_browser = count() > 0, by:{ tag_sn = lower(trim(tag_sn)) }
], sourceField: Shortname, lookupField: tag_sn, fields:{ has_browser }

| lookup [
fetch dt.entity.http_check | expand tags | fieldsAdd tags = lower(tags)
| parse tags, "DATA* 'shortname' DATA* ':' DATA:tag_sn"
| summarize has_http = count() > 0, by:{ tag_sn = lower(trim(tag_sn)) }
], sourceField: Shortname, lookupField: tag_sn, fields:{ has_http }

| lookup [
fetch dt.entity.multiprotocol_monitor | expand tags | fieldsAdd tags = lower(tags)
| parse tags, "DATA* 'shortname' DATA* ':' DATA:tag_sn"
| summarize has_mpm = count() > 0, by:{ tag_sn = lower(trim(tag_sn)) }
], sourceField: Shortname, lookupField: tag_sn, fields:{ has_mpm }

// 7. CALCULATE FOOTPRINT, MONITORING STATUS, AND SCORE
| fieldsAdd
h = coalesce(host_count, 0),
t = coalesce(trace_count, 0),
r = coalesce(rum_count, 0),
b = if(has_browser == true, 1, else: 0),
hc = if(has_http == true, 1, else: 0),
m = if(has_mpm == true, 1, else: 0)
| fieldsAdd
Footprint = (h + t + r + b + hc + m),
// RUM now counts as active monitoring
is_actively_monitored = (h > 0 or t > 0 or r > 0 or (b + hc + m) > 0)
| fieldsAdd
s1 = if(h > 0, 1, else: 0),
s2 = if(t > 0, 1, else: 0),
s3 = if(log_exists == true, 1, else: 0),
s4 = if((b + hc + m) > 0, 1, else: 0),
s5 = if(h > 0 and t > 0, 1, else: 0)
| fieldsAdd
`Obs Score` = toLong(s1 + s2 + s3 + s4 + s5),
`Monitored Status` = if(not is_actively_monitored, "⚠️", else: "✅")

// 8. FINAL VISUALIZATION
| fieldsAdd
OneAgent = if(h > 0, "✅", else: "🔴"),
Traces = if(t > 0, "✅", else: "🔴"),
Logs = if(log_exists == true, "✅", else: "🔴"),
RUM = if(r > 0, "✅", else: "🔴"),
`Any Synth` = if((b + hc + m) > 0, "✅", else: "🔴"),
`Browser Check` = if(has_browser == true, "✅", else: "🔴"),
`HTTP Check` = if(has_http == true, "✅", else: "🔴"),
`Multi-Protocol` = if(has_mpm == true, "✅", else: "🔴")

| fields Shortname, `Obs Score`, Footprint, `Monitored Status`, Criticality, OneAgent, Traces, Logs, RUM, `Any Synth`, `Browser Check`, `HTTP Check`, `Multi-Protocol`, Owner, Lead, Portfolio, MD, VP, `Archer Status` = Status
//| sort `No Monitoring` desc, `Obs Score` asc
//| filter Criticality == "Vital" or Criticality == "Critical"
//| filter `No Monitoring` == "⚠️"
| filter  in(Shortname, $Shortname) and in(Criticality, $Criticality) and in( Portfolio, $Portfolio) and in(MD, $MD) and in(VP, $VP)
| filter `Monitored Status` == "⚠️"

