34.query:
// 1. START WITH METADATA
fetch bizevents, from: now()-72h
| filter dt.system.bucket == "archer" and Status == "Active"
| fieldsAdd Shortname = lower(trim(`Application Short Name`))
| summarize {Portfolio = takeFirst(Portfolio), MD = coalesce(takeFirst(`Managing Director`), takeFirst(MD))}, by:{ Shortname }
// 2-6. COVERAGE LOOKUPS FOR SCORING
| lookup [fetch dt.entity.host | expand tags | parse tags, "DATA* 'shortname' DATA* ':' DATA:tag_sn" | summarize h = count() > 0, by:{ tag_sn = lower(trim(tag_sn)) }], sourceField: Shortname, lookupField: tag_sn, fields:{ h }
| lookup [fetch dt.entity.service | expand tags | parse tags, "DATA* 'shortname' DATA* ':' DATA:tag_sn" | summarize t = count() > 0, by:{ tag_sn = lower(trim(tag_sn)) }], sourceField: Shortname, lookupField: tag_sn, fields:{ t }
| lookup [fetch logs, from:now()-24h, samplingRatio:1000 | filter isNotNull(dt.security_context) | summarize l = count() > 0, by:{ log_sn = lower(dt.security_context) }], sourceField: Shortname, lookupField: log_sn, fields:{ l }
| lookup [fetch dt.entity.application | expand tags | parse tags, "DATA* 'shortname' DATA* ':' DATA:tag_sn" | summarize r = count() > 0, by:{ tag_sn = lower(trim(tag_sn)) }], sourceField: Shortname, lookupField: tag_sn, fields:{ r }
| lookup [fetch dt.entity.synthetic_test |append [fetch dt.entity.multiprotocol_monitor] | append [fetch dt.entity.http_check] | expand tags | parse tags, "DATA* 'shortname' DATA* ':' DATA:tag_sn" | summarize s = count() > 0, by:{ tag_sn = lower(trim(tag_sn)) }], sourceField: Shortname, lookupField: tag_sn, fields:{ s }
// 7. MTTR LOOKUP (30-Day Window)
| lookup [fetch dt.davis.problems, from:now()-30d | fieldsAdd Shortname= arrayDistinct(iCollectArray(splitString(arrayRemoveNulls(iCollectArray(if(matchesPhrase(entity_tags[], "*hortname*"), lower(entity_tags[]))))[], ":")[1])) | expand Shortname | summarize { mttr_raw = avg(toLong(resolved_problem_duration)), total_p = countDistinct(display_id) }, by:{Shortname}], sourceField:Shortname, lookupField:Shortname, fields:{ mttr_raw, total_p }
// 8. INDIVIDUAL APP SCORING LOGIC
| fieldsAdd f1 = if(h==true, 1, else:0), f2 = if(t==true, 1, else:0), f3 = if(l==true, 1, else:0), f4 = if(r==true or s==true, 1, else:0), f5 = if(h==true and t==true, 1, else:0)
| fieldsAdd app_score = (f1 + f2 + f3 + f4 + f5)
// 9. AGGREGATE BY PORTFOLIO AND MD
| summarize {`App Count` = countDistinct(Shortname), `Total Problems` = sum(coalesce(total_p, 0)), `Avg Obs Score` = round(avg(app_score), decimals:2), mttr_ns = avg(coalesce(mttr_raw, 0))}, by:{ Portfolio, MD }
// 10. CLEANUP AND SORT (Needs Improvement at top)
| filter isNotNull(MD) and MD != ""
| sort `Avg Obs Score` asc
// 11. FINAL FORMATTING
| fieldsAdd `Avg MTTR` = if(mttr_ns > 0, concat(toLong(mttr_ns / 60000000000), " min"), else: "0 min")
| fields Portfolio, MD, `App Count`,`Total Problems 30d` = `Total Problems`, `Avg Obs Score`, `Avg MTTR`
| filter in( Portfolio, $Portfolio) and in(MD, $MD)

