52.query:
// 1. START WITH ARCHER METADATA & NORMALIZE FOR JOIN
fetch bizevents, from: now()-72h
| filter dt.system.bucket == "archer" and Status == "Active"
| fieldsAdd pg_normalized = replaceString(lower(trim(`Product Group`)), " ", "_")
| summarize {Original_PG = takeFirst(`Product Group`),Portfolio = takeFirst(Portfolio)}, by:{ pg_normalized }
// 2. LOOKUP LOG INGEST COST
| lookup [fetch bizevents, from: now()-24h | filter matchesPhrase(event.type, "com.product_group.logs") | summarize ingest_bytes = sum(billed_bytes), by:{ usage_bucket = lower(trim(usage_bucket)) }], sourceField: pg_normalized, lookupField: usage_bucket, fields:{ ingest_bytes }
// 3. LOOKUP LOG EXECUTION COST
| lookup [fetch bizevents, from: now()-24h | filter matchesPhrase(event.type, "com.product_group.logs") | summarize exec_bytes = sum(scanned_bytes), by:{ bucket = lower(trim(bucket)) }], sourceField: pg_normalized, lookupField: bucket, fields:{ exec_bytes }
// 4. CALCULATE COSTS (Assume rates: $0.10/GB Ingest, $0.02/GB Exec)
| fieldsAdd ingest_gb = round(coalesce(ingest_bytes, 0) / 1073741824, decimals:2), exec_gb = round(coalesce(exec_bytes, 0) / 1073741824, decimals:2)
| fieldsAdd ingest_cost = round(ingest_gb * 0.10, decimals:2), exec_cost = round(exec_gb * 0.02, decimals:2)
| fieldsAdd total_log_cost = ingest_cost + exec_cost
| sort total_log_cost desc
| fields `Product Group` = Original_PG, Portfolio,`Total Cost ($)` = total_log_cost   // `Ingest (GB)` = ingest_gb, `Execution (GB)` = exec_gb

